// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {BANK_SAFE} from "../src/BANK_SAFE.sol";

contract InvMutTest is Test {
    BANK_SAFE c;
    function setUp() public { c = new BANK_SAFE(); }
    function testFuzz_property(address actor, address depositor, uint256 amount) public {
        LogProbe probe = new LogProbe();
        vm.assume(actor != address(probe) && actor != address(c) && depositor != address(c));
        // c routes its external logging through the deployed probe, its address is the fuzz-chosen lg
        vm.prank(actor);
        c.SetLogFile(address(probe));
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.Deposit{value: amount}();
        // c must have logged through lg: the probe records every AddMessage c emits
        assertTrue(probe.count() == 1);
    }
}

contract LogProbe {
    uint public count;
    function AddMessage(address, uint, string memory) public { count++; }
}
